import React from 'react';
import { MatchStatus, MatchTimeStatus } from '../../data/VotingData';

interface CountdownProps {
    timeLeft: MatchTimeStatus;
}

const Countdown: React.FC<CountdownProps> = ({ timeLeft }) => {
    const formatTime = (time: number) => {
        return time < 10 ? `0${time}` : time.toString();
    };

    let displayTime: string;

    if (timeLeft.days > 0) {
        displayTime = `${timeLeft.days} Tage ${formatTime(timeLeft.hours)} Stunden`;
    } else if (timeLeft.hours > 0) {
        displayTime = `${formatTime(timeLeft.hours)} Stunden ${formatTime(timeLeft.minutes)} Minuten`;
    } else {
        displayTime = `${formatTime(timeLeft.minutes)} Minuten ${formatTime(timeLeft.seconds)} Sekunden`;
    }

    switch (timeLeft.status) {
        case MatchStatus.NOT_STARTED:
            return <div style={{ textAlign: 'center' }}>Abstimmung beginnt in: {displayTime}</div>;
        case MatchStatus.IN_PROGRESS:
            return (
                <div style={{ textAlign: 'center' }}>
                    Abstimmung endet in: {displayTime}
                </div>
            );
        case MatchStatus.ENDED:
            return <div style={{ textAlign: 'center' }}>Die Abstimmung ist beendet.</div>;
        default:
            return null; // Fallback case
    }
};

export default Countdown;