import React from 'react';
import { Button, Card, Container, IconButton, Typography } from '@mui/material';
import MatchDisplay from '../MatchDisplay';
import { format, parseISO } from 'date-fns';
import { de } from 'date-fns/locale';
import { MatchDto } from '../../data/MatchDto';
import HowToVoteIcon from '@mui/icons-material/HowToVote';
import { useNavigate } from 'react-router-dom';

const MatchesByDay: React.FC<{ matches: MatchDto[] }> = ({ matches }) => {

    /**
     * Split the matches from the upcoming weekend into groups by day.
     */
    const matchesByDate = matches.reduce<Record<string, MatchDto[]>>((acc, match) => {
        const date = match.matchDate.split('T')[0]; // Get the date part (YYYY-MM-DD)
        if (!acc[date]) {
            acc[date] = []; // Initialize the array for this date
        }
        acc[date].push(match); // Add the match to the array for this date
        return acc;
    }, {});

    /**
     * Get the weekday for a given date in german.
     */
    const getWeekday = (date: string) => {
        return format(parseISO(date), 'EEEE', { locale: de });
    }

    const navigate = useNavigate();

    const handleNavigateToVote = (matchId:string) => {
        navigate(`/vote/${matchId}`);
    };

    return (
        <Container>
            {Object.entries(matchesByDate).map(([date, matches]) => (
                <div key={date} style={{ marginBottom: '20px' }}>
                    <Typography variant="h4" align='center' style={{ marginTop: '16px' }}>
                        {getWeekday(date)}
                    </Typography>
                    <Typography variant="h6" align='center'>
                        {new Date(date).toLocaleDateString()}
                    </Typography>
                    {matches.map((match) => (
                        <Card key={match.id} style={{ paddingTop: '16px', paddingBottom: '16px', marginTop: '16px'}}>
                            <Typography variant="h6" align='center'>{match.league.name}</Typography>
                            <MatchDisplay
                                homeName={match.homeTeamName}
                                homeLogo={match.homeTeamLogoBase64}
                                guestName={match.guestTeamName}
                                guestLogo={match.guestTeamLogoBase64}
                            />
                            <Typography variant="h5" style={{ textAlign: 'center' }}>
                                {match.matchDate.split('T')[1].substring(0, 5) + ' Uhr'}
                            </Typography>
                            <div style={{ display: 'flex', justifyContent: 'center', marginTop:'16px' }}>
                                <Button
                                    endIcon={<HowToVoteIcon />}
                                    style={{ textAlign: 'center' }}
                                    onClick={() => handleNavigateToVote(match.id)}
                                >
                                    Abstimmen
                                </Button>
                            </div>
                        </Card>
                    ))}
                </div>
            ))}
        </Container>
    );
};

export default MatchesByDay;
