import React, { useEffect } from 'react';
import Cookies from 'js-cookie';
import { v4 as uuidv4 } from 'uuid';

interface CookieBannerProps {
  onClose: () => void; // Function to close the popup
}

const CookieBanner: React.FC<CookieBannerProps> = ({ onClose }) => {
  useEffect(() => {
    Cookies.remove('userId');
  }, []);

  const handleAcceptCookies = () => {
    let userId = uuidv4().replace(/-/g, ''); // Generate a clean UUID
    Cookies.set('userId', userId, { expires: 365, path: '/' }); // Set cookie for 1 year
    onClose(); // Hide the popup
  };

  const handleRejectCookies = () => {
    onClose(); // Close the popup without setting cookies
  };

  return (
    <div style={overlayStyle}>
      <div style={popupStyle}>
        <div style={contentStyle}>
          <h3 style={titleStyle}>Cookies Zustimmung</h3>
          <p>
            Diese Website verwendet Cookies, um Ihre Abstimmungen zu speichern und Ihnen eine bessere Nutzererfahrung zu bieten. Ohne Ihre Zustimmung können Sie leider nicht abstimmen.
          </p>
          <div style={buttonContainerStyle}>
            <button onClick={handleAcceptCookies} style={acceptButtonStyle}>
              Zustimmen
            </button>
            <button onClick={handleRejectCookies} style={rejectButtonStyle}>
              Ablehnen
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// Styles for the backdrop (overlay)
const overlayStyle: React.CSSProperties = {
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100%',
  height: '100%',
  backgroundColor: 'rgba(0, 0, 0, 0.5)', // Semi-transparent background
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  zIndex: 1000,
  animation: 'fadeIn 0.3s ease-in-out', // Animation for smooth appearance
};

const popupStyle: React.CSSProperties = {
  backgroundColor: '#fff',
  color: '#333',
  borderRadius: '8px',
  padding: '1rem', // Changed padding from 2rem to 1rem (16px)
  boxShadow: '0 4px 10px rgba(0, 0, 0, 0.2)',
  width: '300px',
  textAlign: 'center',
  animation: 'scaleUp 0.3s ease-in-out', // Animation for smooth scale-in effect
};

// Content styling (Text and buttons)
const contentStyle: React.CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center',
  alignItems: 'center',
};

const titleStyle: React.CSSProperties = {
  marginBottom: '1rem',
  fontSize: '1.5rem',
  fontWeight: 'bold',
};

const buttonContainerStyle: React.CSSProperties = {
  display: 'flex',
  justifyContent: 'space-around',
  width: '100%',
};

const acceptButtonStyle: React.CSSProperties = {
  padding: '0.7rem 1.5rem',
  backgroundColor: '#28a745',
  color: '#fff',
  border: 'none',
  borderRadius: '5px',
  cursor: 'pointer',
  fontSize: '1rem',
};

const rejectButtonStyle: React.CSSProperties = {
  padding: '0.7rem 1.5rem',
  backgroundColor: '#dc3545',
  color: '#fff',
  border: 'none',
  borderRadius: '5px',
  cursor: 'pointer',
  fontSize: '1rem',
};

export default CookieBanner;
