import { Collapse, Grid, IconButton, IconButtonProps, styled, Typography } from "@mui/material";
import { MatchHistoryDto, Vote } from "../../data/HistoryDto";
import { PlayerDto } from "../../data/MatchDto";
import { useState } from "react";
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';

const getOrderedVotes = (match: MatchHistoryDto): Vote[] => {
    return match.votes
        .filter((vote: Vote) => vote.votingPercentage > 0)
        .sort((a: Vote, b: Vote) => b.votingPercentage - a.votingPercentage);
};

const getPlayerLogo = (player: PlayerDto, match: MatchHistoryDto) => {
    return player.teamName === match.homeTeamName ? match.homeTeamLogoBase64 : match.guestTeamLogoBase64;
}

interface ExpandMoreProps extends IconButtonProps {
    expand: boolean;
}

const ExpandMore = styled((props: ExpandMoreProps) => {
    const { expand, ...other } = props;
    return <IconButton {...other} />;
})(({ theme }) => ({
    marginLeft: 'auto',
    transition: theme.transitions.create('transform', {
        duration: theme.transitions.duration.shortest,
    }),
    variants: [
        {
            props: ({ expand }) => !expand,
            style: {
                transform: 'rotate(0deg)',
            },
        },
        {
            props: ({ expand }) => !!expand,
            style: {
                transform: 'rotate(180deg)',
            },
        },
    ],
}));

const MvpList: React.FC<{ match: MatchHistoryDto }> = ({ match }) => {
    const logoSize = '24px';
    const topPlayers = getOrderedVotes(match);
    const [expanded, setExpanded] = useState(false);

    if (topPlayers.length === 0) {
        return <div></div>;
    }

    const handleExpandClick = () => {
        setExpanded(!expanded);
    };

    return (<div style={{ marginLeft: "16px", marginTop: "16px", marginRight: "16px" }}>
        <Grid container alignItems="center">
            <Grid item>
                <Typography variant="h6" align="left" style={{ marginBottom: "8px" }}>
                    Player of the Match
                </Typography>
            </Grid>
            <ExpandMore
                expand={expanded}
                onClick={handleExpandClick}
                aria-label="show more"
            >
                <ExpandMoreIcon />
            </ExpandMore>
        </Grid>
        <div>
            <Grid container spacing={2} alignItems="center" style={{ textAlign: 'left' }}>
                <Grid item style={{ flex: '0 0 auto' }}>
                    <img
                        src={`data:image/png;base64,${getPlayerLogo(topPlayers[0].player, match)}`}
                        alt="Club Logo"
                        style={{ width: logoSize, height: logoSize }}
                    />
                </Grid>
                <Grid item style={{ flex: '1 1 auto', minWidth: '120px' }}>
                    <Typography variant="body1">
                        {topPlayers[0].player.firstName} {topPlayers[0].player.surname}
                    </Typography>
                </Grid>
                <Grid item style={{ flex: '0 0 auto' }}>
                    <Typography variant="body1" align="right">
                        {topPlayers[0].votingPercentage}%
                    </Typography>
                </Grid>
            </Grid>
        </div>
        <Collapse in={expanded} timeout="auto" unmountOnExit>
            {topPlayers.slice(1).map((playerVote, index) => (
                <Grid container spacing={2} alignItems="center" key={index} style={{ marginTop: "2px", textAlign: 'left' }}>
                    <Grid item style={{ flex: '0 0 auto' }}>
                        {match.homeTeamLogoBase64 ? (
                            <img
                                src={`data:image/png;base64,${getPlayerLogo(playerVote.player, match)}`}
                                alt="Club Logo"
                                style={{ width: logoSize, height: logoSize }}
                            />
                        ) : (
                            <div style={{ width: logoSize, height: logoSize, backgroundColor: '#f0f0f0' }} />
                        )}
                    </Grid>
                    <Grid item style={{ flex: '1 1 auto', minWidth: '120px' }}>
                        <Typography variant="body1">
                            {playerVote.player.firstName} {playerVote.player.surname}
                        </Typography>
                    </Grid>
                    <Grid item style={{ flex: '0 0 auto' }}>
                        <Typography variant="body1" align="right">
                            {playerVote.votingPercentage}%
                        </Typography>
                    </Grid>
                </Grid>
            ))}
        </Collapse>

    </div>);
}

export default MvpList;