import { useEffect, useState } from 'react';
import { MatchDto } from '../../data/MatchDto';
import LinearProgress from '@mui/material/LinearProgress';
import MatchesByDay from '../../components/voting/MatchesByDate';
import Typography from '@mui/material/Typography/Typography';
import ApiProvider from '../../data/ApiProvider';

const UpcomingMatches = () => {
    const [upcomingMatches, setUpcomingMatches] = useState<MatchDto[] | null>(null);
    const [loading, setLoading] = useState<boolean>(true);

    useEffect(() => {
        const fetchUpcomingMatches = async () => {
            setLoading(true);
            try {
                const response = await fetch(ApiProvider.API_ROOT + '/api/match/week');
                if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
                const jsonResponseBody = await response.text();
                if (!jsonResponseBody) {
                    setLoading(false);
                    setUpcomingMatches(null);
                } else {
                    const data: MatchDto[] = JSON.parse(jsonResponseBody);
                    setUpcomingMatches(data);
                }
            } catch (error) {
                console.error('Error fetching upcoming matches:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchUpcomingMatches();
    }, []);

    if (loading) {
        return <LinearProgress color="secondary" />;
    } else if (upcomingMatches == null || upcomingMatches.length === 0) {
        return <Typography variant="h5" align="center" style={{ margin: "16px" }}>
            Keine Spiele am kommdenden Wochenende!
        </Typography>;
    }
    return (
        <div>
            <MatchesByDay matches={upcomingMatches} />
        </div>
    );
};

export default UpcomingMatches;