import React from 'react';
import {Grid, Typography} from '@mui/material';

export interface MatchDisplayProps {
  homeName: string;
  homeLogo: string;
  guestName: string;
  guestLogo: string;
  homeGoals?: number;
  guestGoals?: number;
}

const MatchDisplay: React.FC<MatchDisplayProps> = ({homeName, homeLogo, guestName, guestLogo, homeGoals, guestGoals}) => {
  const logoSize = '40px';

  return (
    <Grid container direction="column" alignItems="center" justifyContent="center">
      <Grid item>
        <Grid container spacing={1} alignItems="center" justifyContent="center">
          <Grid item>
            {homeLogo ? (
              <img
                src={`data:image/png;base64,${homeLogo}`}
                alt={homeName}
                style={{width: logoSize, height: logoSize, paddingLeft: '4px'}}
              />
            ) : (
              <div style={{width: logoSize, height: logoSize, backgroundColor: '#f0f0f0'}}/>
            )}
          </Grid>
          <Grid item>
            <Typography variant="h4" component="span" style={{margin: '0 8px'}}>
              {homeName.replaceAll(' ', '').toUpperCase().substring(0, 3)}
            </Typography>
          </Grid>
          <Grid item>
            <Typography variant="h4" component="span" style={{margin: '0 8px'}}>
              {homeGoals != null && guestGoals != null ? `${homeGoals} : ${guestGoals}` : ':'}
            </Typography>
          </Grid>

          <Grid item>
            <Typography variant="h4" component="span" style={{margin: '0 8px'}}>
              {guestName.replaceAll(' ', '').toUpperCase().substring(0, 3)}
            </Typography>
          </Grid>

          <Grid item>
            {guestLogo ? (
              <img
                src={`data:image/png;base64,${guestLogo}`}
                alt={guestName}
                style={{width: logoSize, height: logoSize, paddingRight: '4px'}}
              />
            ) : (
              <div style={{width: logoSize, height: logoSize, backgroundColor: '#f0f0f0'}}/>
            )}
          </Grid>
        </Grid>
      </Grid>
    </Grid>
  );
};

export default MatchDisplay;
