/**
 * Enum for the status of a match. The status defines whether the voting is possible or not.
 * IN_PROGRESS is the only status where voting shall be possible.
 */
export enum MatchStatus {
    NOT_STARTED = "not started",
    IN_PROGRESS = "in progress",
    ENDED = "ended"
}

export interface MatchTimeStatus {
    days: number;
    hours: number;
    minutes: number;
    seconds: number;
    status: MatchStatus;
}