import { BrowserRouter as BrowserRouter, Route, Routes } from 'react-router-dom';
import './App.css';
import Navbar from './components/Navbar';
import Voting from './pages/voting/Voting';
import History from './pages/History';
import UpcomingMatches from './pages/voting/UpcomingMatches';
import CookieBanner from './components/CookieBanner';
import { useEffect, useState } from 'react';
import Cookies from 'js-cookie';

function App() {
  const [isPopupVisible, setPopupVisible] = useState(false);

  // Check if the cookie is set on app load
  useEffect(() => {
    const userId = Cookies.get('userId');
    if (!userId) {
      setPopupVisible(true); // Show the banner if the cookie is not set
    }
  }, []);

  const handleCloseCookieBanner = () => {
    setPopupVisible(false); // Hide the popup when accepted or rejected
  };
  return (
    <BrowserRouter>
      {isPopupVisible && <CookieBanner onClose={handleCloseCookieBanner} />}
      <Navbar/>
      <Routes>
        <Route path="" element={<UpcomingMatches />} />
        <Route path="/vote/:matchId" element={<Voting />} />
        <Route path="/history" element={<History />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
