import React from "react";
import {MatchHistoryDto} from "../../data/HistoryDto";
import {Card, Typography} from "@mui/material";
import MatchDisplay from "../MatchDisplay";
import MvpList from "./MvpList";

const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('de-DE', { 
        day: 'numeric', 
        month: 'long', 
        year: 'numeric' 
    }).format(date);
};

const MatchResult: React.FC<{ matchHistory: MatchHistoryDto }> = ({matchHistory}) => {
    return (
        <Card style={{paddingTop: '16px', paddingBottom: '16px', marginTop: '16px'}}>
            <Typography variant="h5" align='center'>{matchHistory.league.name}</Typography>
            <Typography variant="body2" align='center'>{formatDate(matchHistory.matchDate)}</Typography>
            <MatchDisplay
                homeName={matchHistory.homeTeamName}
                homeLogo={matchHistory.homeTeamLogoBase64}
                guestName={matchHistory.guestTeamName}
                guestLogo={matchHistory.guestTeamLogoBase64}
                homeGoals={matchHistory.homeGoals}
                guestGoals={matchHistory.guestGoals}
            />
            <MvpList match={matchHistory}/>
        </Card>);
}

export default MatchResult;
