import AppBar from '@mui/material/AppBar';
import Typography from '@mui/material/Typography';
import IconButton from '@mui/material/IconButton';
import {Link} from 'react-router-dom';
import logo from '../assets/logo.webp';
import {Toolbar} from '@mui/material';


export default function Navbar() {
  return (
    <AppBar position="sticky">
      <Toolbar>
        <IconButton edge="start" color="inherit" aria-label="logo" component={Link} to="/">
          <img src={logo} alt="logo" style={{width: '50px', height: '50px', marginRight: '10px'}}/>
        </IconButton>
        <Typography variant="h6" component={Link} to="/"
                    style={{color: 'inherit', textDecoration: 'none', marginRight: '20px'}}>
          Abstimmung
        </Typography>
        <Typography variant="h6" component={Link} to="/history" style={{color: 'inherit', textDecoration: 'none'}}>
          Verlauf
        </Typography>
      </Toolbar>
    </AppBar>
  );
};

