import { useEffect, useState } from 'react';
import { Container, Button, LinearProgress } from '@mui/material';
import MatchDisplay from '../../components/MatchDisplay';
import TeamPlayerTable from '../../components/voting/TeamPlayerTable';
import Countdown from "../../components/voting/Countdown";
import { PlayerDto, MatchDto } from "../../data/MatchDto";
import { useParams } from 'react-router-dom';
import { MatchStatus, MatchTimeStatus } from '../../data/VotingData';
import ApiProvider from '../../data/ApiProvider';
import Cookies from 'js-cookie';
import CookieBanner from '../../components/CookieBanner';

const hasAcceptedCookies = (): boolean => {
    return getVoterToken() !== undefined;
};

const getVoterToken = (): String | undefined => {
    return Cookies.get('userId');
}

const Voting = () => {
    const { matchId } = useParams();

    const [match, setMatch] = useState<MatchDto | null>(null);
    const [selectedPlayer, setSelectedPlayer] = useState<PlayerDto | null>(null);
    const [votedPlayer, setVotedPlayer] = useState<PlayerDto | null>(null);
    const [loading, setLoading] = useState<boolean>(true);
    const [matchStatus, setMatchStatus] = useState<MatchTimeStatus | null>(null);
    const [isPopupVisible, setPopupVisible] = useState(false);

    /**
     * Fetch the details of the match with the given matchId.
     */
    useEffect(() => {
        const fetchNextMatch = async () => {
            setLoading(true);
            setMatch(null);
            try {
                const response = await fetch(ApiProvider.API_ROOT + `/api/match/${matchId}`);
                if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
                const jsonResponseBody = await response.text();
                if (!jsonResponseBody) {
                    setLoading(false);
                    setMatch(null);
                } else {
                    const data: MatchDto = JSON.parse(jsonResponseBody);
                    setMatch(data);

                    // Check if the user has already voted
                    if (hasAcceptedCookies()) {
                        const voterToken = getVoterToken();
                        const voteResponse = await fetch(ApiProvider.API_ROOT + `/api/vote/check?matchId=${matchId}&voterToken=${voterToken}`);
                        if (voteResponse.ok) {
                            const votedPlayerId = await voteResponse.json();
                            if (votedPlayerId) {
                                let voted = data.players.find(player => player.id === String(votedPlayerId)) || null;
                                setSelectedPlayer(voted);
                                setVotedPlayer(voted);
                            }
                        }
                    }
                    setMatchStatus(calculateTimeLeft(data));
                }
            } catch (error) {
                console.error('Error fetching the next match:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchNextMatch();
    }, [matchId]);

    const matchDurationMs = 60 * 60 * 1000; // 1 hour in milliseconds

    const handleShowCookieBanner = () => {
        setPopupVisible(true); // Show the cookie banner
    };

    const handleCloseCookieBanner = () => {
        setPopupVisible(false); // Close the cookie banner
    };

    const calculateTimeLeft = (match: MatchDto): MatchTimeStatus => {
        const matchDate = new Date(match.matchDate);
        const difference = matchDate.getTime() - new Date().getTime();
        let timeLeft: MatchTimeStatus = { days: 0, hours: 0, minutes: 0, seconds: 0, status: MatchStatus.NOT_STARTED };

        if (difference > 0) {
            const totalSeconds = Math.floor(difference / 1000);
            timeLeft = {
                days: Math.floor(totalSeconds / (60 * 60 * 24)),
                hours: Math.floor((totalSeconds % (60 * 60 * 24)) / (60 * 60)),
                minutes: Math.floor((totalSeconds % (60 * 60)) / 60),
                seconds: totalSeconds % 60,
                status: MatchStatus.NOT_STARTED,
            };
        } else if (difference <= 0 && difference >= -matchDurationMs) {
            const matchEnd = matchDate.getTime() + matchDurationMs;
            const matchRemaining = matchEnd - new Date().getTime();
            const totalSeconds = Math.floor(matchRemaining / 1000);
            timeLeft = {
                days: 0,
                hours: Math.floor(totalSeconds / (60 * 60)),
                minutes: Math.floor((totalSeconds % (60 * 60)) / 60),
                seconds: totalSeconds % 60,
                status: MatchStatus.IN_PROGRESS,
            };
        } else {
            timeLeft.status = MatchStatus.ENDED;
        }

        return timeLeft;
    };

    useEffect(() => {
        const timer = setInterval(() => {
            if (match) {
                setMatchStatus(calculateTimeLeft(match)); // Update status every second
            }
        }, 1000);

        return () => clearInterval(timer);
    }, [match]); // Update timer when match changes

    /**
     * If no data could be found for the given matchId, display a message.
     */
    if (loading) {
        return <LinearProgress color="secondary" />;
    } else if (!loading && match == null) {
        return <Container>Kein Spiel verfügbar</Container>
    } else if (match == null) {
        return <Container>Kein Spiel verfügbar</Container>
    }

    const handlePlayerSelect = (player: PlayerDto | null) => {
        if (isMatchInProgress) {
            setSelectedPlayer(player);
        }
    };

    /**
     * Send the vote to the backend.
     */
    const playerVoted = async () => {
        if (Cookies.get('userId') == undefined) {
            handleShowCookieBanner();
        } else if (selectedPlayer != null) {
            try {
                const voterToken = getVoterToken();
                const response = await fetch(ApiProvider.API_ROOT + `/api/vote?playerId=${selectedPlayer.id}&matchId=${match.id}&voterToken=${voterToken}`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                });

                if (response.ok) {
                    setVotedPlayer(selectedPlayer);
                } else {
                    const errorMessage = await response.text();
                    console.error('Vote not accepted:', errorMessage);
                }
            } catch (error) {
                console.error('Error while voting:', error);
            }
        }
    };

    /**
     * Remove the vote from the backend.
     */
    const removeSelection = async () => {
        try {
            const voterToken = getVoterToken();
            const response = await fetch(ApiProvider.API_ROOT + `/api/vote?matchId=${match.id}&voterToken=${voterToken}`, {
                method: 'DELETE',
                headers: {
                    'Content-Type': 'application/json',
                },
            });
            if (response.ok) {
                setSelectedPlayer(null);
                setVotedPlayer(null);
            }
        } catch (error) {
            console.error('Error while deleting vote:', error);
        }
    };

    let isMatchInProgress = matchStatus?.status === MatchStatus.IN_PROGRESS;

    return (
        <>
        {isPopupVisible && <CookieBanner onClose={handleCloseCookieBanner} />}
        <Container style={{ marginTop: '16px' }}>
            <MatchDisplay
                homeName={match.homeTeamName}
                homeLogo={match.homeTeamLogoBase64}
                guestName={match.guestTeamName}
                guestLogo={match.guestTeamLogoBase64}
            />
            <div style={{ marginBottom: '16px' }} />
            {votedPlayer == null &&
                <>
                    <TeamPlayerTable
                        homeTeamLogo={match.homeTeamLogoBase64}
                        guestTeamLogo={match.guestTeamLogoBase64}
                        homeTeamName={match.homeTeamName}
                        players={match.players}
                        onPlayerSelect={handlePlayerSelect}
                        selectedPlayer={selectedPlayer}
                        enableSelection={true}
                    />
                    <div style={{ marginBottom: '16px' }} />
                    {matchStatus && <Countdown timeLeft={matchStatus} />}
                    <div style={{ marginBottom: '16px' }} />
                    <div style={{ textAlign: 'center' }}>
                        <Button
                            color="primary"
                            variant="contained"
                            disabled={!isMatchInProgress || selectedPlayer == null}
                            onClick={playerVoted}
                        >
                            Abstimmen
                        </Button>
                    </div>
                </>
            }
            {votedPlayer != null &&
                <>
                    <h4 style={{ textAlign: 'center' }}>Ihre Auswahl:</h4>
                    <TeamPlayerTable
                        homeTeamLogo={match.homeTeamLogoBase64}
                        guestTeamLogo={match.guestTeamLogoBase64}
                        homeTeamName={match.homeTeamName}
                        players={[votedPlayer]}
                        onPlayerSelect={() => {
                        }}
                        selectedPlayer={selectedPlayer}
                        enableSelection={false}
                    />
                    <div style={{ marginBottom: '16px' }} />
                    {matchStatus && <Countdown timeLeft={matchStatus} />}
                    <div style={{ marginBottom: '16px' }} />
                    <div style={{ textAlign: 'center' }}>
                        <Button
                            color="primary"
                            variant="contained"
                            disabled={!isMatchInProgress || selectedPlayer == null}
                            onClick={removeSelection}
                        >
                            Auswahl ändern
                        </Button>
                    </div>
                </>
            }
            <div style={{ marginBottom: '16px' }} />
        </Container>
        </>
    );
};

export default Voting;