import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  palette: {
    primary: {
      main: '#000000', // Schwarz
    },
    secondary: {
      main: 'rgb(91, 152, 102)', // Grün
    },
    background: {
      default: '#ffffff', // Weiß
    },
    text: {
      primary: '#000000', // Schwarz
      secondary: '#ffffff', // Weiß
    },
  },
  typography: {
    fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
    h1: {
      fontSize: '2rem',
      fontWeight: 700,
    },
    h2: {
      fontSize: '1.75rem',
      fontWeight: 700,
    },
    h3: {
      fontSize: '1.5rem',
      fontWeight: 700,
    },
    h4: {
      fontSize: '1.25rem',
      fontWeight: 700,
    },
    h5: {
      fontSize: '1rem',
      fontWeight: 700,
    },
    h6: {
      fontSize: '0.875rem',
      fontWeight: 700,
    },
    body1: {
      fontSize: '1rem',
      fontWeight: 500,
    },
    body2: {
      fontSize: '0.875rem',
      fontWeight: 500,
    },
    button: {
      fontSize: '1rem',
      fontWeight: 700,
      color: '#ffffff', // Weiße Schriftfarbe in Buttons
    },
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          fontSize: '0.875rem',
          textTransform: 'none',
          backgroundColor: 'rgb(91, 152, 102)', // Grün für die Buttons
          color: '#ffffff', // Weiße Schriftfarbe in den Buttons
          '&:hover': {
            backgroundColor: 'rgba(91, 152, 102, 0.8)', // Dunkleres Grün beim Hover
          },
        },
      },
    },
    MuiAppBar: {
      styleOverrides: {
        root: {
          backgroundColor: '#000000', // Schwarz für die Navbar
        },
      },
    },
    MuiToolbar: {
      styleOverrides: {
        root: {
          color: '#ffffff', // Weiße Schriftfarbe in der Navbar
        },
      },
    },
  },
});

export default theme;
