import { useEffect, useState } from 'react';
import {
    Container,
    LinearProgress,
    Pagination,
} from '@mui/material';
import MatchResult from "../components/history/MatchResult";
import SelectCategory from '../components/history/SelectCategory';
import { MatchHistoryDto } from '../data/HistoryDto';
import ApiProvider from '../data/ApiProvider';

const History = () => {
    const [matches, setMatches] = useState<MatchHistoryDto[]>([]);
    const [loading, setLoading] = useState<boolean>(true);
    const [leagues, setLeagues] = useState<string[]>(["Alle"]);
    const [selectedLeague, setSelectedLeague] = useState<number>(0);
    const [pageData, setPageData] = useState<{ size: number, totalElements: number, totalPages: number, number: number }>({ size: 2, totalElements: 0, totalPages: 1, number: 0 });
    const [links, setLinks] = useState<{ [key: string]: string | null }>({ next: null, prev: null, self: null });
    const [page, setPage] = useState<number>(0);
    const size = 5;

    useEffect(() => {
        const fetchLeagues = async () => {
            try {
                const response = await fetch(ApiProvider.API_ROOT + '/api/league/name');
                if (!response.ok) {
                    throw new Error(`Error: ${response.statusText}`);
                }
                const data = await response.json();
                setLeagues(["Alle", ...data]);
            } catch (error) {
                console.error("Failed to fetch leagues:", error);
            }
        };

        fetchLeagues(); // Fetch leagues on initial load
    }, []);

    useEffect(() => {
        const fetchMatches = async () => {
            try {
                const leagueParam = selectedLeague === 0 ? "" : `&leagueName=${leagues[selectedLeague]}`;
                const response = await fetch(ApiProvider.API_ROOT + `/api/match/past?page=${page}&size=${size}${leagueParam}`);
                if (!response.ok) {
                    throw new Error(`Error: ${response.statusText}`);
                }
                const data = await response.json();

                setMatches(data._embedded.historyMatchDtoList);
                setPageData(data.page);
                setLinks({
                    next: data._links.next?.href || null,
                    prev: data._links.prev?.href || null,
                    self: data._links.self?.href || null,
                });
            } catch (error) {
                console.error("Failed to fetch past matches:", error);
            }
        };

        setLoading(true); // Set loading before fetching matches
        fetchMatches().finally(() => setLoading(false)); // Ensure loading state is reset after fetching
    }, [selectedLeague, page]);

    if (loading) {
        return <LinearProgress color="secondary" />;
    }

    return (
        <Container style={{ marginTop: '16px' }}>
            <SelectCategory
                selectedIndex={selectedLeague}
                categories={leagues}
                onCategoryChange={(index: number) => setSelectedLeague(index)}
            />
            {matches.map((match) => (
                <MatchResult key={match.id} matchHistory={match} />
            ))}
            <div style={{ display: 'flex', justifyContent: 'center', marginTop: '16px', marginBottom: '16px' }}>
                <Pagination
                    count={pageData.totalPages}
                    page={pageData.number + 1}
                    color="secondary"
                    size="large"
                    onChange={(_, value) => setPage(value - 1)}
                />
            </div>
        </Container>
    );
};

export default History;