import React from 'react';
import {Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Typography} from '@mui/material';
import {PlayerDto} from "../../data/MatchDto";

interface TeamPlayerTableProps {
    homeTeamLogo: string;
    guestTeamLogo: string;
    homeTeamName: string;
    players: PlayerDto[];
    onPlayerSelect: (player: PlayerDto | null) => void;
    selectedPlayer: PlayerDto | null;
    enableSelection: boolean;
}

const TeamPlayerTable: React.FC<TeamPlayerTableProps> = ({
                                                             homeTeamLogo,
                                                             guestTeamLogo,
                                                             homeTeamName,
                                                             players,
                                                             onPlayerSelect,
                                                             selectedPlayer,
                                                             enableSelection
                                                         }) => {
    return (
        <TableContainer component={Paper}>
            <Table>
                <TableHead>
                    <TableRow>
                        <TableCell align="center" style={{width: 'auto'}}>Team</TableCell>
                        <TableCell align="center" style={{width: 'auto'}}>Nummer</TableCell>
                        <TableCell align="left" style={{width: '100%'}}>Name</TableCell>
                    </TableRow>
                </TableHead>
                <TableBody>
                    {players.map((player) => (
                        <TableRow key={player.id} onClick={() => {
                            if (selectedPlayer != null && player.id == selectedPlayer.id) {
                                onPlayerSelect(null);
                            } else {
                                onPlayerSelect(player)
                            }
                        }}
                                  style={enableSelection && selectedPlayer != null && selectedPlayer.id == player.id ? {backgroundColor: 'rgba(91, 152, 102, 0.3)'} : {}}>
                            <TableCell align="center" style={{width: 'auto'}}>
                                <img
                                    src={`data:image/png;base64,${player.teamName === homeTeamName ? homeTeamLogo : guestTeamLogo}`}
                                    alt={player.teamName}
                                    style={{ width: '28px', height: '28px' }}
                                />
                            </TableCell>
                            <TableCell align="left" style={{width: 'auto'}}>
                                <Typography variant="body1">
                                    {player.jerseyNumber}
                                </Typography>
                            </TableCell>
                            <TableCell align="left" style={{width: '100%'}}>
                                <Typography variant="body2">
                                    {player.surname}, {player.firstName}
                                </Typography>
                            </TableCell>
                        </TableRow>
                    ))}
                </TableBody>
            </Table>
        </TableContainer>
    );
};

export default TeamPlayerTable;
